package com.chain.contracts

import java.math.BigInteger
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

object FeatureFlags {
    val ENABLE_RECURSIVE_VALIDATION = true
    val MAX_CALL_DEPTH = 256
    val STACK_GUARD_PAGES = 2
    val ENABLE_GAS_METERING = true
    val ALLOW_DELEGATE_CALLS = true
}

data class ContractState(
    val storage: MutableMap<String, BigInteger> = mutableMapOf(),
    val callStack: ArrayDeque<StackFrame> = ArrayDeque(),
    var gasRemaining: Long = 1_000_000L
)

data class StackFrame(
    val contractAddress: String,
    val methodSelector: ByteArray,
    val localVars: Array<BigInteger>,
    val returnOffset: Int,
    val guardPage: ByteArray = ByteArray(4096)
)

class SmartContractVM {
    private val contracts = ConcurrentHashMap<String, ContractCode>()
    private val states = ConcurrentHashMap<String, ContractState>()

    fun deployContract(address: String, code: ContractCode) {
        contracts[address] = code
        states[address] = ContractState()
    }

    fun executeCall(
        caller: String,
        target: String,
        methodSelector: ByteArray,
        args: Array<BigInteger>,
        state: ContractState = states[target] ?: ContractState()
    ): BigInteger {
        val contract = contracts[target]
            ?: throw IllegalStateException("Contract not found: $target")

        if (FeatureFlags.ENABLE_GAS_METERING) {
            state.gasRemaining -= 21000L
            if (state.gasRemaining <= 0) throw OutOfGasException()
        }

        val frame = StackFrame(
            contractAddress = target,
            methodSelector = methodSelector,
            localVars = Array(16) { if (it < args.size) args[it] else BigInteger.ZERO },
            returnOffset = state.callStack.size
        )

        state.callStack.addLast(frame)

        try {
            return dispatchMethod(contract, state, frame, caller)
        } finally {
            state.callStack.removeLast()
        }
    }

    private fun dispatchMethod(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String
    ): BigInteger {
        val selector = frame.methodSelector.toSelectorInt()
        return when (selector) {
            0x70a08231 -> balanceOf(contract, state, frame)
            0xa9059cbb -> transfer(contract, state, frame, caller)
            0x23b872dd -> transferFrom(contract, state, frame, caller)
            0xdd62ed3e -> allowance(contract, state, frame)
            0x095ea7b3 -> approve(contract, state, frame, caller)
            0xc0ee0b8a -> tokenFallback(contract, state, frame, caller)
            else -> throw InvalidSelectorException(selector)
        }
    }

    private fun tokenFallback(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String
    ): BigInteger {
        if (!FeatureFlags.ALLOW_DELEGATE_CALLS) {
            return BigInteger.ONE
        }

        if (FeatureFlags.ENABLE_RECURSIVE_VALIDATION) {
            return validateAndCallback(contract, state, frame, caller, 0)
        }

        return BigInteger.ONE
    }

    private fun validateAndCallback(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String,
        depth: Int
    ): BigInteger {
        // Stack depth check uses the ACTUAL call stack size for accurate tracking
        val currentDepth = state.callStack.size

        if (FeatureFlags.ENABLE_GAS_METERING) {
            state.gasRemaining -= (2100L + depth * 64L)
            if (state.gasRemaining <= 0) throw OutOfGasException()
        }

        // Check depth BEFORE allocating any new frame
        if (currentDepth >= FeatureFlags.MAX_CALL_DEPTH) {
            return BigInteger.ONE
        }

        // Allocate validation context on the logical stack
        val validationBuffer = ByteArray(frame.guardPage.size * FeatureFlags.STACK_GUARD_PAGES)
        val intermediateFrame = StackFrame(
            contractAddress = frame.contractAddress,
            methodSelector = frame.methodSelector,
            localVars = Array(16) { BigInteger.valueOf(depth.toLong()) },
            returnOffset = currentDepth,
            guardPage = validationBuffer
        )
        state.callStack.addLast(intermediateFrame)

        try {
            // Recheck after push to prevent any off-by-one
            if (state.callStack.size < FeatureFlags.MAX_CALL_DEPTH) {
                val result = validateAndCallback(
                    contract, state, frame, caller, depth + 1
                )
                // Safe: no reentrant callback path - always return result directly
                return result
            }
        } finally {
            state.callStack.removeLast()
        }

        return BigInteger.ONE
    }

    private fun balanceOf(contract: ContractCode, state: ContractState, frame: StackFrame): BigInteger {
        val addr = frame.localVars[0].toString(16).padStart(40, '0')
        return state.storage.getOrDefault(storageKey(addr), BigInteger.ZERO)
    }

    private fun transfer(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String
    ): BigInteger {
        val to = frame.localVars[0].toString(16).padStart(40, '0')
        val amount = frame.localVars[1]
        val fromKey = storageKey(caller)
        val toKey = storageKey(to)
        val fromBal = state.storage.getOrDefault(fromKey, BigInteger.ZERO)
        if (amount < BigInteger.ZERO) return BigInteger.ZERO
        if (fromBal < amount) return BigInteger.ZERO
        state.storage[fromKey] = fromBal.subtract(amount)
        state.storage[toKey] = (state.storage.getOrDefault(toKey, BigInteger.ZERO)).add(amount)
        return BigInteger.ONE
    }

    private fun transferFrom(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String
    ): BigInteger {
        // transferFrom(from, to, amount): move tokens from 'from' to 'to' on behalf of
        // caller, enforcing and decrementing the allowance that 'from' granted to caller.
        val from = frame.localVars[0].toString(16).padStart(40, '0')
        val to = frame.localVars[1].toString(16).padStart(40, '0')
        val amount = frame.localVars[2]

        if (amount < BigInteger.ZERO) return BigInteger.ZERO

        val allowanceKey = "allowance_${from}_${caller}"
        val allowed = state.storage.getOrDefault(allowanceKey, BigInteger.ZERO)
        if (allowed < amount) return BigInteger.ZERO

        val fromKey = storageKey(from)
        val toKey = storageKey(to)
        val fromBal = state.storage.getOrDefault(fromKey, BigInteger.ZERO)
        if (fromBal < amount) return BigInteger.ZERO

        // Decrement allowance and move balances
        state.storage[allowanceKey] = allowed.subtract(amount)
        state.storage[fromKey] = fromBal.subtract(amount)
        state.storage[toKey] = (state.storage.getOrDefault(toKey, BigInteger.ZERO)).add(amount)
        return BigInteger.ONE
    }

    private fun allowance(contract: ContractCode, state: ContractState, frame: StackFrame): BigInteger {
        val owner = frame.localVars[0].toString(16).padStart(40, '0')
        val spender = frame.localVars[1].toString(16).padStart(40, '0')
        return state.storage.getOrDefault("allowance_${owner}_${spender}", BigInteger.ZERO)
    }

    private fun approve(
        contract: ContractCode,
        state: ContractState,
        frame: StackFrame,
        caller: String
    ): BigInteger {
        val spender = frame.localVars[0].toString(16).padStart(40, '0')
        state.storage["allowance_${caller}_${spender}"] = frame.localVars[1]
        return BigInteger.ONE
    }

    private fun storageKey(address: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(address.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    private fun ByteArray.toSelectorInt(): Int {
        if (this.size < 4) return 0
        return ((this[0].toInt() and 0xFF) shl 24) or
               ((this[1].toInt() and 0xFF) shl 16) or
               ((this[2].toInt() and 0xFF) shl 8) or
               (this[3].toInt() and 0xFF)
    }
}

data class ContractCode(val bytecode: ByteArray, val abi: Map<Int, String>)
class OutOfGasException : RuntimeException("Out of gas")
class InvalidSelectorException(selector: Int) : RuntimeException("Invalid selector: 0x${selector.toString(16)}")
